/// Invoices from a directory (`*.json`) or from a single file, sorted by name so a run is reproducible.
/// Bounded: a merchant channel may not decide how much this process reads.
const MAX_INVOICE_FILES: usize = 1000;
const MAX_INVOICE_BYTES: u64 = 262_144; // far above any real invoice

fn load_invoices(path: &Path) -> Result<Vec<Invoice>> {
    let mut files: Vec<PathBuf> = Vec::new();
    if path.is_dir() {
        for entry in std::fs::read_dir(path)
            .with_context(|| format!("reading the invoice directory {}", path.display()))?
        {
            let entry = entry?;
            let candidate = entry.path();
            if candidate.extension().is_some_and(|e| e == "json") {
                files.push(candidate);
            }
        }
    } else {
        files.push(path.to_path_buf());
    }
    files.sort();
    if files.len() > MAX_INVOICE_FILES {
        bail!(
            "{} invoice files in {} exceeds the cap of {MAX_INVOICE_FILES} - refusing to read a merchant directory this large",
            files.len(),
            path.display()
        );
    }
    let mut invoices = Vec::new();
    for file in &files {
        let meta = std::fs::symlink_metadata(file)
            .with_context(|| format!("statting the invoice {}", file.display()))?;
        if !meta.file_type().is_file() {
            bail!(
                "{} is not a regular file - refusing to read it as an invoice",
                file.display()
            );
        }
        if meta.len() > MAX_INVOICE_BYTES {
            bail!(
                "invoice {} is {} bytes, above the {MAX_INVOICE_BYTES}-byte cap",
                file.display(),
                meta.len()
            );
        }
        let text = std::fs::read_to_string(file)
            .with_context(|| format!("reading the invoice {}", file.display()))?;
        let invoice: Invoice = serde_json::from_str(&text)
            .with_context(|| format!("parsing the invoice {}", file.display()))?;
        invoices.push(invoice);
    }
    Ok(invoices)
}
